using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEngine.InputSystem;using Newtonsoft.Json;
public static class BNFinal {
 public static object Run(){AssetDatabase.ImportAsset("Assets/Afrer_Seconds/06.Data/AssetSources/B2_DomeNetwork.json",ImportAssetOptions.ForceSynchronousImport);var s=SceneManager.GetActiveScene();var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var probes=all.SelectMany(t=>t.GetComponents<ReflectionProbe>()).ToArray();var result=new{scene=s.path,saved=!s.isDirty,playing=Application.isPlaying,mouse=Mouse.current.enabled,keyboard=Keyboard.current.enabled,Application.runInBackground,occlusionBaking=StaticOcclusionCulling.isRunning,camerasUseOcclusion=all.SelectMany(t=>t.GetComponents<Camera>()).All(c=>c.useOcclusionCulling),probes=probes.Length,missingProbeTextures=probes.Count(p=>!p.customBakedTexture),activeLights=all.Where(t=>t.gameObject.activeInHierarchy).Sum(t=>t.GetComponents<Light>().Length),missingMeshes=all.Where(t=>t.gameObject.activeInHierarchy).SelectMany(t=>t.GetComponents<MeshFilter>()).Count(f=>!f.sharedMesh)};string o=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Docs/Review/2026-11-10_B2_DomeNetwork/"));File.WriteAllText(o+"final_state.json",JsonConvert.SerializeObject(result,Formatting.Indented));File.WriteAllText(o+"unity_final_state.json",JsonConvert.SerializeObject(all.Where(t=>t.name.StartsWith("B2_")).Select(t=>new{t.name,position=new[]{t.position.x,t.position.y,t.position.z},active=t.gameObject.activeInHierarchy}),Formatting.Indented));return result;}
}
